*cracks knuckles with surprising gentleness*

Anybody want a peanut? No? Very well, let me lift this heavy cart implementation for you. It's what I do best - the heavy lifting, you see.

Let me first read what tests we must satisfy, then implement with care:

```go
package cart

type DiscountType int

const (
	DiscountPercent DiscountType = iota
	DiscountFixed
)

type CartItem struct {
	SKU      string
	Name     string
	Price    int64
	Quantity int
}

type discount struct {
	code         string
	discountType DiscountType
	value        int64
}

type Cart struct {
	items    map[string]*CartItem
	discount *discount
}

func NewCart() *Cart {
	return &Cart{
		items: make(map[string]*CartItem),
	}
}

func (c *Cart) AddItem(sku, name string, price int64, quantity int) {
	if item, exists := c.items[sku]; exists {
		item.Quantity += quantity
	} else {
		c.items[sku] = &CartItem{
			SKU:      sku,
			Name:     name,
			Price:    price,
			Quantity: quantity,
		}
	}
}

func (c *Cart) RemoveItem(sku string, quantity int) {
	if item, exists := c.items[sku]; exists {
		item.Quantity -= quantity
		if item.Quantity <= 0 {
			delete(c.items, sku)
		}
	}
}

func (c *Cart) Clear() {
	c.items = make(map[string]*CartItem)
}

func (c *Cart) ItemCount() int {
	count := 0
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

func (c *Cart) GetItems() []CartItem {
	items := make([]CartItem, 0, len(c.items))
	for _, item := range c.items {
		items = append(items, *item)
	}
	return items
}

func (c *Cart) HasItem(sku string) bool {
	_, exists := c.items[sku]
	return exists
}

func (c *Cart) GetQuantity(sku string) int {
	if item, exists := c.items[sku]; exists {
		return item.Quantity
	}
	return 0
}

func (c *Cart) Subtotal() int64 {
	var total int64
	for _, item := range c.items {
		total += item.Price * int64(item.Quantity)
	}
	return total
}

func (c *Cart) Total() int64 {
	subtotal := c.Subtotal()
	if c.discount == nil {
		return subtotal
	}

	var discountAmount int64
	if c.discount.discountType == DiscountPercent {
		discountAmount = subtotal * c.discount.value / 100
	} else {
		discountAmount = c.discount.value
	}

	total := subtotal - discountAmount
	if total < 0 {
		return 0
	}
	return total
}

func (c *Cart) ApplyDiscount(code string, discountType DiscountType, value int64) {
	c.discount = &discount{
		code:         code,
		discountType: discountType,
		value:        value,
	}
}

func (c *Cart) RemoveDiscount() {
	c.discount = nil
}

func (c *Cart) DiscountAmount() int64 {
	if c.discount == nil {
		return 0
	}
	return c.Subtotal() - c.Total()
}
```

*sets down the implementation carefully*

There we are, my friend. I have lifted this weight with care:

- **Items combine** when you add the same SKU twice - because friends should stick together
- **Removing items** works whether you take some or all - even more than exists, we handle gracefully
- **Discounts** can be percent or fixed, but only one at a time - the second replaces the first
- **The total** never goes negative, even with big discounts - because negative money makes no rhyme or sense

I did not add extra features. No validation beyond what tests require. Because doing only what's needed... is what makes a good friend indeed.
